import{_ as r,o as a,c as t,a2 as o}from"./chunks/framework.DqYch1Cg.js";const d=JSON.parse('{"title":"前端性能诊断自测","description":"","frontmatter":{},"headers":[],"relativePath":"学习自测/06opt/q_opt_4-performance_review.md","filePath":"学习自测/06opt/q_opt_4-performance_review.md","lastUpdated":1794211306000}'),n={name:"学习自测/06opt/q_opt_4-performance_review.md"};function s(i,e,p,c,h,l){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="前端性能诊断自测" tabindex="-1">前端性能诊断自测 <a class="header-anchor" href="#前端性能诊断自测" aria-label="Permalink to &quot;前端性能诊断自测&quot;">​</a></h1><h2 id="_1-你会从哪里开始优化一个慢页面" tabindex="-1">1. 你会从哪里开始优化一个慢页面？ <a class="header-anchor" href="#_1-你会从哪里开始优化一个慢页面" aria-label="Permalink to &quot;1. 你会从哪里开始优化一个慢页面？&quot;">​</a></h2><p><strong>参考回答：</strong> 先说明慢的场景与指标，收集真实用户分布，再在可控环境复现。通过 Network、Performance、服务端追踪定位主因，选改动做对照，确认体验收益、错误率和成本，而不是一次加入全部优化技巧。</p><p><strong>追问：</strong> LCP、INP、CLS 分别衡量什么？为什么 TTFB 不能完全等于服务端执行时间？见<a href="/FE-prepare-interview/概念与原理/06opt/s_opt_10-measurement">性能测量</a>。</p><h2 id="_2-资源越合并越好吗" tabindex="-1">2. 资源越合并越好吗？ <a class="header-anchor" href="#_2-资源越合并越好吗" aria-label="Permalink to &quot;2. 资源越合并越好吗？&quot;">​</a></h2><p><strong>参考回答：</strong> 合并减少部分请求开销，却可能增加无用下载、解析和缓存失效。HTTP/2 / 3 已支持多路复用，应结合页面路径拆包与复用；压缩、CDN、按需加载和移除未用代码都应有数据依据。</p><p><strong>追问：</strong> Brotli 很有效，为什么 JavaScript 主线程时间仍然高？压缩不减少解压后的解析执行工作量。</p><h2 id="_3-图片怎样同时兼顾速度和稳定性" tabindex="-1">3. 图片怎样同时兼顾速度和稳定性？ <a class="header-anchor" href="#_3-图片怎样同时兼顾速度和稳定性" aria-label="Permalink to &quot;3. 图片怎样同时兼顾速度和稳定性？&quot;">​</a></h2><p><strong>参考回答：</strong> 先控制实际像素与质量，用合适格式与回退，通过 srcset / sizes 适配设备，显式宽高预留空间。关键首屏图避免懒加载，非关键屏外图延后加载，必要时用 IntersectionObserver。Base64 只适合经过权衡的场景，不是一律更快。</p><p><strong>追问：</strong> 给全部图片 preload / fetchpriority=high 为什么可能拖慢主图？</p><h2 id="_4-回流重绘怎样定位-而不是靠口诀" tabindex="-1">4. 回流重绘怎样定位，而不是靠口诀？ <a class="header-anchor" href="#_4-回流重绘怎样定位-而不是靠口诀" aria-label="Permalink to &quot;4. 回流重绘怎样定位，而不是靠口诀？&quot;">​</a></h2><p><strong>参考回答：</strong> 用面板确认布局和绘制成本，重点查读写交错造成的同步布局、大 DOM 与长任务。批量读写、局部更新和虚拟列表各有适用条件。transform / opacity 有合成优化机会，但不是绝对无成本，opacity=0 仍可能可聚焦或可点击。</p><p><strong>追问：</strong> 创建 DocumentFragment 一定比直接追加快吗？不要脱离浏览器批处理和真实负载下结论。</p><h2 id="_5-缓存失效与上线更新如何协调" tabindex="-1">5. 缓存失效与上线更新如何协调？ <a class="header-anchor" href="#_5-缓存失效与上线更新如何协调" aria-label="Permalink to &quot;5. 缓存失效与上线更新如何协调？&quot;">​</a></h2><p><strong>参考回答：</strong> 带内容哈希的静态资源可长期缓存，HTML 入口需要及时验证，旧资源留一段时间保证旧页面可用。no-cache 不等于不存储，no-store 不等于清空旧缓存；CDN 与 Service Worker 要分别设计版本和失效策略。</p><p><strong>追问：</strong> worker 更新后旧页面仍开着怎么办？Cache Storage 为什么不能简单当成 HTTP 缓存的同一层？</p><h2 id="_6-预加载、懒加载和离线能力有什么代价" tabindex="-1">6. 预加载、懒加载和离线能力有什么代价？ <a class="header-anchor" href="#_6-预加载、懒加载和离线能力有什么代价" aria-label="Permalink to &quot;6. 预加载、懒加载和离线能力有什么代价？&quot;">​</a></h2><p><strong>参考回答：</strong> 预加载提前使用带宽，懒加载延迟非关键工作，离线缓存提高断网可用性，但都引入资源争抢、陈旧内容和状态维护。Service Worker 不会永久运行，也不应缓存所有已登录 API。</p><p><strong>验证任务：</strong> 设计一次冷缓存、热缓存、弱网、离线、发布新版本的对照实验，记录观察结果，避免只报告一次分数。</p><blockquote><p>来源：<a href="https://github.com/Fridolph/Fridolph/tree/c3a1eda8e0f7fe08d8ec54e07d07db514cbfc5d7/interviewMap/%E6%80%A7%E8%83%BD" target="_blank" rel="noreferrer">个人 interviewMap / 性能</a>；<a href="https://web.dev/articles/vitals" target="_blank" rel="noreferrer">Web Vitals</a>；结合<a href="/FE-prepare-interview/概念与原理/06opt/intro">前端性能学习入口</a>继续实践。</p></blockquote>',20)])])}const f=r(n,[["render",s]]);export{d as __pageData,f as default};
